def pick_addr(url, cc=None, rc=None):
    cc = (cc or "").upper()
    rc = (rc or "").upper()
    dom = urlparse(url).netloc
    tcn = dom.split('.')[-1].upper()

    if tcn in book:
        return book[tcn]

    ccn = C2C.get(cc)

    if rc in book and ccn == rc:
        return book[rc]
    elif rc in book:
        return book[rc]
    return book["DEFAULT"]

def _json(resp):
    try:
        data = resp.json()
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}

def capture(data, first, last):
    try:
        start = data.index(first) + len(first)
        end = data.index(last, start)
        return data[start:end]
    except ValueError:
        return None

def capture_any(data, patterns):
    for first, last in patterns:
        result = capture(data, first, last)
        if result:
            return result
    return None

def get_product_id(response):
    response_data = _json(response)

    products_data = response_data.get("products") or []
    products = {}
    fallback = {}
    for product in products_data:
        variants = product.get("variants") or product.get("productVariants") or []
        for variant in variants:
            product_id = variant.get("id") or variant.get("variantId")
            available = variant.get("available")
            raw_price = variant.get("price") or variant.get("amount")
            try:
                price = float(raw_price)
            except (TypeError, ValueError):
                continue
            if price < 0.1:
                continue
            if product_id is None:
                continue
            if available is None or available:
                products[product_id] = price
            else:
                fallback[product_id] = price
    if products:
        min_price_product_id = min(products, key=products.get)
        return min_price_product_id, products[min_price_product_id]
    if fallback:
        min_price_product_id = min(fallback, key=fallback.get)
        return min_price_product_id, fallback[min_price_product_id]
    return None
    
