# Flask Setup
app = Flask(__name__)

def build_proxy(proxy_str):
    if not proxy_str:
        return None
    parts = proxy_str.split(":")
    if len(parts) == 4:
        host, port, user, pw = parts
        return f"http://{user}:{pw}@{host}:{port}"
    if len(parts) == 2:
        return f"http://{proxy_str}"
    return None

async def run_check(url, card, proxy=None):
    async with httpx.AsyncClient(
        timeout=90, follow_redirects=True, proxy=build_proxy(proxy)
    ) as session:
        return await autoshopify(url, card, session)

def do_check():
    args = request.args
    data = request.get_json(force=True, silent=True) or {}
    form = request.form

    url = (
        args.get("site") or args.get("url")
        or data.get("site") or data.get("url")
        or form.get("site") or form.get("url")
    )
    card = (
        args.get("cc") or args.get("card")
        or data.get("cc") or data.get("card")
        or form.get("cc") or form.get("card")
    )
    proxy = (
        args.get("proxy") or data.get("proxy") or form.get("proxy")
    )

    if not url or not card:
        return jsonify({"Response": "MISSING site/cc", "Status": False}), 400

    try:
        out = asyncio.run(run_check(url, card, proxy))
    except Exception as e:
        err = f"{type(e).__name__}: {e}" if str(e) else type(e).__name__
        out = {"Response": err, "Status": False}
    return jsonify(out)

@app.get("/shopify")
@app.post("/shopify")
def shopify():
    return do_check()

@app.get("/check")
@app.post("/check")
def check():
    return do_check()

@app.get("/health")
def health():
    return jsonify({"status": "ok", "service": "api2"})

@app.get("/")
def index():
    return jsonify({
        "service": "api2",
        "endpoints": {
            "GET /shopify?cc=CARD&site=URL&proxy=host:port:user:pass": "run check",
            "POST /check": "json {\"url\":..., \"card\":..., \"proxy\":...}",
            "GET /health": "ping",
        },
    })

@app.after_request
def cors(resp):
    resp.headers["Access-Control-Allow-Origin"] = "*"
    resp.headers["Access-Control-Allow-Methods"] = "GET, POST, OPTIONS"
    resp.headers["Access-Control-Allow-Headers"] = "Content-Type"
    return resp

@app.errorhandler(404)
def not_found(e):
    return jsonify({
        "Response": "NOT FOUND",
        "Status": False,
        "hint": "GET /shopify?cc=CARD&site=URL&proxy=host:port:user:pass",
    }), 404

@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({"Response": "METHOD NOT ALLOWED", "Status": False}), 405

@app.errorhandler(500)
def server_error(e):
    return jsonify({"Response": "SERVER ERROR", "Status": False}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8899, threaded=True)
